#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void layernorm_kernel(const float* x, const float* mean, const float* var, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // Broadcast the global mean and variance to this element
        out[idx] = (val - mean[idx]) / sqrtf(var[idx] + 1e-5f);
    }
}

torch::Tensor layernorm_cuda(torch::Tensor x) {
    auto size = x.numel();
    float eps = 1e-5f;

    // Allocate output
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

